export function priceAfterDiscount(subtotalCents, policy) {
  if (!Number.isSafeInteger(subtotalCents) || subtotalCents < 0) throw new TypeError("subtotalCents must be a non-negative integer");
  const tiers = [...(policy.tiers ?? [])].sort((a, b) => a.minimumCents - b.minimumCents);
  const tier = tiers.filter((item) => subtotalCents >= item.minimumCents).at(-1);
  const percent = tier?.percent ?? policy.percent ?? 0;
  if (!Number.isInteger(percent) || percent < 0 || percent > 100) throw new TypeError("discount percent must be an integer from 0 to 100");
  return subtotalCents - Math.floor((subtotalCents * percent) / 100);
}
